  shared_transport_params: array<vec4<u32>, 10>,
  // A1 direct-dispatch snapshot, bytes 240..255 (see
  // SCHROEDER_SPATIAL_FIELD_CONSUMER_DIRECT_DISPATCH_MAGIC).
  dispatch_snapshot: vec4<u32>,
